  }

  get cadenceDraft() {
    return ref('');
  }

  get saving() {
    return ref(false);
  }

  get loading() {
    return ref(true);
  }

  get cadenceDirty() {
    return (
      Number(this.cadenceDraft.value) !==
      (this.settings.value?.cadenceHours ?? 0)
    );
  }

  get saveDisabled() {
